回傳格式：
```
// responses
{
  "code": number  
  "data": {
    "success": number,  //成功筆數
    "fail": number,     //失敗筆數
    "errorData": [row, row...]   //失敗資料 
  }
}
// 解析資料結果範例  錯誤為object
row = {
  "rowIndex": number,    //資料行數
  "year": 2023,          //年
  "month": 8,            //月
  "day": 2,              //日
  "hour": 8,             //時
  "min": 8,              //分
  "sec": 0,              //秒
  "date": "2023/08/02",  //日期
  "time": "08:08:00",    //時間
  "clock": "002",        //卡鐘
  "empNo": {             //員工編號
    "key": "empNo",
    "value": "D001",
    "invalid": "無此員工編號"
  },
}
// 錯誤 object
err = {
  "key": string,      //錯誤項目
  "value": string,    //取得值
  "invalid": string   //錯誤訊息
}
```

